1728	    pub(crate) fn register_physical_thread(
1729	        &mut self,
1730	        dettid: DetTid,
1731	        mm: MmId,
1732	        physical_pid: i32,
1733	        physical_tid: i32,
1734	    ) -> std::io::Result<()> {
1735	        if physical_pid <= 0 || physical_tid <= 0 {
1736	            return Err(std::io::Error::new(
1737	                std::io::ErrorKind::InvalidInput,
1738	                "host process and thread IDs must be positive",
1739	            ));
1740	        }
1741	        if let Some((known_mm, known_pid, known_tid, _)) = self.physical_thread_pidfds.get(&dettid)
1742	        {
1743	            if *known_mm == mm && *known_pid == physical_pid && *known_tid == physical_tid {
1744	                return Ok(());
1745	            }
1746	            if *known_mm == mm {
1747	                return Err(std::io::Error::new(
1748	                    std::io::ErrorKind::AlreadyExists,
1749	                    format!(
1750	                        "scheduler identity {dettid} already names host process {known_pid} thread {known_tid}"
1751	                    ),
1752	                ));
1753	            }
1754	        }
1755	        let raw_fd = unsafe {
1756	            libc::syscall(
1757	                libc::SYS_pidfd_open,
1758	                physical_tid,
1759	                libc::O_EXCL as libc::c_uint,
1760	            )
1761	        };
1762	        if raw_fd < 0 {
1763	            return Err(std::io::Error::last_os_error());
1764	        }
1765	        // SAFETY: pidfd_open returned a new descriptor owned by this process.
1766	        let pidfd = unsafe { OwnedFd::from_raw_fd(raw_fd as libc::c_int) };
1767	        self.physical_thread_pidfds
1768	            .insert(dettid, (mm, physical_pid, physical_tid, pidfd));
1769	        Ok(())
1770	    }
