3020	    /// Send a signal to the guest. A scheduler-parked thread is made runnable immediately. SaBRe
3021	    /// external syscalls remain blocked until the signal interrupts them and their real
3022	    /// continuation RPC becomes visible; other backends retain their existing immediate requeue.
3023	    fn signal_guest(&mut self, dettid: DetTid, signal: Signal) {
3024	        debug!(
3025	            "[dtid {}] deliver signal {} physically to guest thread.",
3026	            dettid, signal
3027	        );
3028	        let result = if let Some((_, _, _, pidfd)) = self.physical_thread_pidfds.get(&dettid) {
3029	            let rc = unsafe {
3030	                libc::syscall(
3031	                    libc::SYS_pidfd_send_signal,
3032	                    pidfd.as_raw_fd(),
3033	                    signal as libc::c_int,
3034	                    std::ptr::null::<libc::siginfo_t>(),
3035	                    0,
3036	                )
3037	            };
3038	            if rc < 0 {
3039	                Err(nix::errno::Errno::last())
3040	            } else {
3041	                Ok(())
3042	            }
3043	        } else if self.backend_requires_thread_directed_process_signals {
3044	            self.terminal_deadlock.get_or_insert_with(|| {
3045	                format!(
3046	                    "HERMIT_DEADLOCK: scheduler cannot deliver signal {} to dettid {} without its host thread pidfd",
3047	                    signal, dettid,
3048	                )
3049	            });
3050	            return;
3051	        } else {
3052	            let pid = Pid::from_raw(dettid.as_raw()); // TODO(T78538674): virtualize pid/tid:
3053	            signal::kill(pid, signal)
3054	        };
