3056	            Ok(()) => {}
3057	            // ⚠️ ESRCH IS AN EXPECTED OUTCOME HERE, NOT AN ERROR. The target
3058	            // chose to exit between the moment it was selected and the moment
3059	            // the signal was sent; that window is inherent and cannot be closed
3060	            // by locking, because the thread's exit is the guest's decision.
3061	            // There is no one left to signal and nothing left to wake, so the
3062	            // correct behaviour is to say so and carry on.
3063	            //
3064	            // This is NOT a retry and NOT a widened catch: exactly ESRCH is
3065	            // absorbed, and every other errno still panics, because a signal
3066	            // rejected for any other reason means the scheduler's model of the
3067	            // guest is wrong and continuing would compound it.
3068	            //
3069	            // WHY IT MATTERED. Before this, the unconditional `expect` turned
3070	            // that ordinary race into a panic on the scheduler task -- and a
3071	            // panicking scheduler does not fail the run, it HANGS it, because
3072	            // every guest thread is waiting on a task that no longer exists.
3073	            // Measured 2026-08-25: `hermit run --backend kvm --strict --verify`
3074	            // on a bash process-substitution pipeline ran 420 s with empty
3075	            // stdout and never exited. The pipeline's short-lived subshells hit
3076	            // this window repeatedly. Found only once the 22 `run_kvm_` cli
3077	            // tests were scheduled; nothing had ever run them.
3078	            Err(nix::errno::Errno::ESRCH) => {
3079	                info!(
3080	                    "[dtid {}] signal {} not delivered: the thread exited before it landed. \
3081	                     Expected race; nothing to deliver and nothing to wake.",
3082	                    dettid, signal
3083	                );
3084	                return;
3085	            }
3086	            Err(errno) => panic!("signal::kill to go through, got {errno}"),
3087	        }
3088	        self.wake_signaled_guest(dettid, signal);
3089	    }
