3092	    /// queued a physical signal for it. The signal itself is not sent here;
3093	    /// this only prevents an internal polling request from hiding a pending
3094	    /// signal indefinitely.
3095	    fn wake_signaled_guest(&mut self, dettid: DetTid, signal: Signal) {
