3130	                    .next_turns
3131	                    .get(&dettid)
3132	                    .and_then(|next_turn| next_turn.req.try_read())
3133	                    .is_some_and(|request| {
3134	                        request.is_ok_and(|resources| {
3135	                            resources
3136	                                .resources
3137	                                .contains_key(&ResourceID::InternalIOPolling)
3138	                        })
3139	                    });
3140	
3141	                if is_internal_io_polling {
3142	                    assert!(self.run_queue.remove_tid(dettid));
3143	                    let mut rsrcs = Resources::new(dettid);
3144	                    rsrcs.insert(
3145	                        ResourceID::InboundSignal(SigWrapper::from(signal)),
3146	                        Permission::W,
3147	                    );
3148	                    self.force_unblock_thread(dettid, rsrcs);
3149	                }
3150	                // TODO(T137242449): other runnable requests could be reprioritized to run
3151	                // sooner, but for now we leave their priorities alone.
3152	            }
3153	            ThreadStatus::NotRunning => {
