3631	                let _ = writeln!(out, "    {}: {}", Self::render_deadline(deadline), evt);
3632	            }
3633	        }
3634	
3635	        if self.blocked.external_io_blockers.is_empty() {
3636	            let _ = writeln!(out, "  external IO blockers: none");
3637	        } else {
3638	            // BTreeMap: already ordered by dettid.
3639	            let _ = writeln!(
3640	                out,
3641	                "  external IO blockers ({}), by dettid:",
3642	                self.blocked.external_io_blockers.len()
3643	            );
3644	            for (dettid, op) in self.blocked.external_io_blockers.iter() {
3645	                let _ = writeln!(out, "    dtid {}: {:?}", dettid, op);
3646	            }
3647	        }
3648	
3649	        if self.blocked.rt_sigsuspend_blockers.is_empty() {
3650	            let _ = writeln!(out, "  rt_sigsuspend blockers: none");
3651	        } else {
3652	            let _ = writeln!(
3653	                out,
3654	                "  rt_sigsuspend blockers ({}), by dettid:",
3655	                self.blocked.rt_sigsuspend_blockers.len()
3656	            );
3657	            for (dettid, op) in self.blocked.rt_sigsuspend_blockers.iter() {
