4020	    /// Replace the request Ivar for `dettid` with a copy with `poll_attempt = 0`,
4021	    /// indicating the poll request is runnable on the next trip through the run queue.
4022	    ///
4023	    /// Precondition: The guest is stopped, so that no one is potentially using the request Ivar.
4024	    /// The request Ivar should also be full with the passed resources
4025	    fn upgrade_polled_to_runnable(&mut self, dettid: DetTid, rs: &Resources) {
4026	        let mut retry_rs = rs.clone();
4027	        retry_rs.poll_attempt = 0;
4028	        let runnable_req = Ivar::full(Ok(retry_rs.clone()));
4029	        let req = &mut self
4030	            .next_turns
4031	            .get_mut(&dettid)
4032	            .expect("nextturn present")
4033	            .req;
4034	        debug_assert!(req.try_read().unwrap().is_ok()); // Ivar should be full
4035	        trace!(
4036	            "[dtid {}] Upgrading polled resource request in {} to runnable non-polled in {}",
4037	            dettid, req, runnable_req
4038	        );
4039	        let previous = std::mem::replace(req, runnable_req.clone());
4040	        // This is the same logical operation with a fresh scheduler request.
4041	        // Keep parked ownership attached while the daemon holds exclusive access.
4042	        self.rebind_parked_request(dettid, &previous, &runnable_req, rs, &retry_rs);
4043	    }
