4600	    fn inbound_signals(&self, dettid: DetTid) -> Vec<SigWrapper> {
4601	        let req = &self.next_turns.get(&dettid).unwrap().req;
4602	        let mut signals = Vec::new();
4603	        if let Some(Ok(resources)) = req.try_read() {
4604	            for resource in resources.resources.keys() {
4605	                match resource {
4606	                    ResourceID::InboundSignal(signal) => signals.push(*signal),
4607	                    ResourceID::WaitidSignals(batch) => signals.extend(batch.iter().copied()),
4608	                    _ => {}
4609	                }
4610	            }
4611	        }
4612	        // A signal can legitimately appear in both an `InboundSignal` and a
4613	        // merged `WaitidSignals` batch. Sort then dedup so the reported set is a
4614	        // canonical function of WHICH signals are pending, not of how many
4615	        // resources happen to carry each one or of the order they arrived in.
4616	        signals.sort_by_key(|signal| signal.0 as libc::c_int);
4617	        signals.dedup_by_key(|signal| signal.0 as libc::c_int);
4618	        signals
4619	    }
