5916	    /// F3: a run-queue removal requested while a tentative_pop window is live
5917	    /// (an asynchronous exec reconnect racing the daemon) must be deferred, not
5918	    /// applied through `remove_tid`'s `tentative_selection.is_none()` guard, and
5919	    /// a pending-removal thread whose `next_turns` entry is already gone must not
5920	    /// crash `are_all_quiesced`. The removal lands at the next drain.
5921	    /// ITEM 1 REGRESSION: a NON-LEADER thread is live, even though it is not a
5922	    /// kill target.
5923	    ///
5924	    /// `process_signal_targets` models `kill(2)`, whose first act is to refuse
5925	    /// anything that is not a thread-group leader. `sched_setattr(2)` and its
5926	    /// relatives resolve through `find_task_by_vpid`, which finds any live
5927	    /// task. Answering the second question with the first resolver reports
5928	    /// ESRCH for a thread that is plainly running, so the two must stay
5929	    /// distinguishable -- this test fails the moment `thread_is_live` is
5930	    /// reduced to the kill resolver.
5931	    #[test]
5932	    fn a_non_leader_thread_is_live_without_being_a_kill_target() {
5933	        let mut sched = Scheduler::new(&Config::default());
5934	        let leader = DetTid::from_raw(11);
5935	        let member = DetTid::from_raw(12);
5936	        let stranger = DetTid::from_raw(13);
5937	        sched.thread_tree.add_child(leader, leader, true);
5938	        sched.thread_tree.add_child(leader, member, false);
5939	        register_known_thread(&mut sched, leader);
5940	        register_known_thread(&mut sched, member);
5941	
5942	        assert!(sched.thread_is_live(leader), "the leader is obviously live");
5943	        assert!(
5944	            sched.thread_is_live(member),
5945	            "a non-leader thread of a live group is live; sched_setattr must reach it"
5946	        );
5947	        assert!(
5948	            !sched.thread_is_live(stranger),
5949	            "a tid that was never registered is not live"
5950	        );
5951	
5952	        // The distinction being preserved: the kill resolver still declines the
5953	        // non-leader, which is correct for kill(2) and wrong for sched_setattr.
5954	        assert!(
5955	            sched.process_signal_targets(member).is_empty(),
5956	            "kill(2) semantics: a non-leader is not a signal target, which is \
5957	             exactly why it is the wrong resolver for a tid lookup"
5958	        );
5959	        assert!(
5960	            !sched.process_signal_targets(leader).is_empty(),
5961	            "the leader is a signal target, so the fixture is wired correctly"
5962	        );
