8359	              "events": {
8360	                "main_write":   {"thread": "main",   "syscalls": 47},
8361	                "worker_write": {"thread": "worker", "syscalls": 8}
8362	              },
8363	              "edges": [ {"before": "main_write", "after": "worker_write", "strength": "hard"} ]
8364	            }"#,
8365	        );
