1352	    fn retain_joined(&self, payload: crate::failure::owned_future::PanicPayload) -> crate::Error {
1353	        let error = {
1354	            self.error
1355	                .lock()
1356	                .expect("KVM child panic owner lock poisoned")
1357	                .clone()
1358	        }
1359	        .unwrap_or_else(|| Arc::new(crate::Error::GuestWorkerPanic));
