1453	    /// Fence a callback-announced transition before polling arbitrary Tool
1454	    /// code. A concurrent nonblocking parent wait may still poll a genuinely
1455	    /// running `Pending` child, but it must wait through this bounded state so
1456	    /// the callback prefix cannot make the parent runnable before waitability.
1457	    pub(crate) fn begin_publication(&self) -> bool {
1458	        let mut state = self
1459	            .state
1460	            .lock()
1461	            .expect("KVM child completion lock poisoned");
1462	        if matches!(*state, ChildCompletionState::Pending) {
1463	            *state = ChildCompletionState::PublicationFenced;
1464	            true
1465	        } else {
1466	            false
1467	        }
1468	    }
1469	
1470	    /// Complete a transition previously armed by [`Self::begin_publication`].
1471	    /// The mutex is never held while Tool code runs.
1472	    pub(crate) fn publish_after_fence(&self, completion: ChildCompletion) -> bool {
1473	        let mut state = self
1474	            .state
1475	            .lock()
1476	            .expect("KVM child completion lock poisoned");
1477	        let published = if matches!(*state, ChildCompletionState::PublicationFenced) {
1478	            *state = ChildCompletionState::Ready(completion);
1479	            true
1480	        } else {
1481	            false
1482	        };
1483	        drop(state);
1484	        if published {
1485	            self.changed.notify_all();
1486	        }
1487	        published
1488	    }
1489	
1490	    /// Publish a direct logical wait result exactly once. Callback-driven
1491	    /// publication uses the explicit fenced pair above. A consumed result
1492	    /// remains terminal, so later physical-cleanup failure cannot resurrect or
1493	    /// replace it.
1494	    pub(crate) fn publish(&self, completion: ChildCompletion) -> bool {
1495	        let mut state = self
1496	            .state
1497	            .lock()
1498	            .expect("KVM child completion lock poisoned");
1499	        if matches!(*state, ChildCompletionState::Pending) {
1500	            *state = ChildCompletionState::Ready(completion);
1501	            true
1502	        } else {
1503	            false
1504	        }
1505	    }
1506	
1507	    pub(crate) fn fail_if_pending(&self) -> bool {
1508	        let mut state = self
1509	            .state
1510	            .lock()
1511	            .expect("KVM child completion lock poisoned");
1512	        let failed = if matches!(
1513	            *state,
1514	            ChildCompletionState::Pending | ChildCompletionState::PublicationFenced
1515	        ) {
1516	            *state = ChildCompletionState::Failed;
1517	            true
1518	        } else {
1519	            false
1520	        };
1521	        drop(state);
1522	        if failed {
