+                    );
+                }
+                1 => {
+                    let rendered = result.unwrap_err().to_string();
+                    assert!(
+                        rendered.contains("still requiring unsupported reparenting"),
+                        "zombie descendant, root pid {root_pid}: {rendered}"
+                    );
